// The Employee Clock-in/out web form's time picker. The web form's script uses the
// `tempusDominus` global the library's UMD build defines, so the bundle defines the same one.
import * as tempusDominus from "@eonasdan/tempus-dominus";

window.tempusDominus = tempusDominus;
